// A: Number of holes
A := int(1,10);   // A e' DISCRETA: lo slider scatta all'intero al rilascio
float numHoles = max(floor(A + 0.5), 1.0); 

// Compute the offset to keep the shape perfectly centered
float offset_u = (numHoles - 1.0) / 2.0;

// Initialize with an out-of-scale distance value
float d_final = 10000.0; 

// We "trick" the program's auto-formatter using int(0.0) and int(20.0).
// This way the GPU gets the exact data with no conversion errors.
for(int k = int(0.0); k < int(20.0); k++) {

    // Convert back to float safely for the spatial math
    float fk = float(k);

    if(fk < numHoles) { 
        // Center on the X axis for this specific ring
        float cx = (fk - offset_u) * max(D, 0.1);

        // Local coordinates
        vec3 p_ring = vec3(p.x - cx, p.y, p.z);

        // Build the single torus (hole)
        float d_ring = length(vec2(length(p_ring.xy) - B, p_ring.z)) - C;

        // Using int(0.0) here for the same reason, to avoid errors on ==
        if(k == int(0.0)) {
            d_final = d_ring; 
        } else {
            d_final = -smax(-d_final, -d_ring, max(E, 0.01));
        }
    }
}

return d_final;
